function Lamp(watts) {
  this.power = String(watts);
}
Lamp.prototype.brighter = function () {
  return this.power + "+";
};

module.exports = {
  count: "3",
  label: 7,
  sizes: { length: 2, 0: 1, 1: 2 },
  ready: "no",
  half: function (n) {
    return n / 2 + " halves";
  },
  settings: { depth: null },
  Lamp: Lamp,
};
